// KPI Library - Master definitions for all 8 domains
// Module 4 Phase 4A — v2: aligned to real 25-column test-datasets
// ⚠️  ALL KPIs map to the ACTUAL 25 columns in test-datasets/[domain]/*.csv:
//   timestamp, record_id, entity_id, entity_segment, entity_region,
//   target_id, target_category, target_subcategory, event_style, event_channel,
//   status, metric_1_value, metric_2_time_ms, metric_3_rate, metric_4_physical,
//   metric_5_financial, flag_1_active, flag_2_priority, context_1, context_2,
//   tag_1, tag_2, version_code, coord_x, coord_y
//
// DOMAIN MEANINGS per column:
//   ecommerce  → metric_1=order_value, metric_2=latency_ms, metric_3=conversion_rate, metric_4=temp_warehouse, metric_5=profit
//   edtech     → metric_1=lesson_progress, metric_2=video_duration_ms, metric_3=completion_rate, metric_4=quiz_score, metric_5=revenue_per_session
//   retail     → metric_1=basket_value, metric_2=checkout_time_ms, metric_3=sell_through_rate, metric_4=footfall_density, metric_5=margin
//   saas       → metric_1=usage_events, metric_2=api_latency_ms, metric_3=retention_rate, metric_4=cpu_usage_pct, metric_5=mrr
//   finance    → metric_1=transaction_amount, metric_2=processing_time_ms, metric_3=approval_rate, metric_4=risk_score, metric_5=net_revenue
//   healthcare → metric_1=vitals_score, metric_2=wait_time_ms, metric_3=treatment_success_rate, metric_4=patient_temp, metric_5=claim_value
//   manufacturing → metric_1=units_produced, metric_2=cycle_time_ms, metric_3=yield_rate, metric_4=machine_temp, metric_5=production_cost
//   services   → metric_1=billable_hours, metric_2=response_time_ms, metric_3=sla_met_rate, metric_4=csat_score, metric_5=invoice_value

import type { DomainType } from '../prisma';
import { DOMAIN_ALIASES } from './semantic-column-aliases';

export interface KPIDefinition {
    id: string;
    name: string;
    domain: DomainType;
    description: string;
    requiredFields: string[];
    formulaTemplate: string;
    aggregationRules: { function: string; column: string }[];
    defaultVisualizationHint: string;
    columnAliases: Record<string, string[]>;
    category: string;
    priority: number;
    // Continuous-data fields for forecasting
    isContinuous?: boolean;
    forecastable?: boolean;
    sourceFiles?: string[]; // which of the 10 theme files this KPI applies to
}

/**
 * Helper to enrich a list of KPIs with the latest semantic aliases for their domain.
 */
function enrichKPIs(kpis: KPIDefinition[], domain: DomainType): KPIDefinition[] {
    const domainAliases = DOMAIN_ALIASES[domain] || {};
    return kpis.map(kpi => {
        const enhancedAliases: Record<string, string[]> = { ...kpi.columnAliases };
        for (const field of kpi.requiredFields) {
            const globalAliases = (domainAliases as any)[field] || [];
            if (globalAliases.length > 0) {
                enhancedAliases[field] = Array.from(new Set([...(enhancedAliases[field] || []), ...globalAliases]));
            }
        }
        return { ...kpi, columnAliases: enhancedAliases };
    });
}

