// ─── ALL KPIS MAP ─────────────────────────────────────────────────────────────────

export const ALL_DOMAIN_KPIS: Record<DomainType, KPIDefinition[]> = {
    ECOMMERCE: ECOMMERCE_KPIS,
    EDTECH: EDTECH_KPIS,
    RETAIL: RETAIL_KPIS,
    SAAS: SAAS_KPIS,
    FINANCE: FINANCE_KPIS,
    HEALTHCARE: HEALTHCARE_KPIS,
    MANUFACTURING: MANUFACTURING_KPIS,
    SERVICES: SERVICES_KPIS,
};

export function getKPIsForDomain(domain: DomainType): KPIDefinition[] {
    return ALL_DOMAIN_KPIS[domain] || [];
}

export function getContinuousKPIs(domain: DomainType): KPIDefinition[] {
    return getKPIsForDomain(domain).filter(k => k.isContinuous);
}

export function getForecastableKPIs(domain: DomainType): KPIDefinition[] {
    return getKPIsForDomain(domain).filter(k => k.forecastable);
}

export function getKPIsBySourceFile(domain: DomainType, fileTheme: string): KPIDefinition[] {
    return getKPIsForDomain(domain).filter(k => k.sourceFiles?.includes(fileTheme));
}

